import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router-dom';

function UpdateArtist() {
  const [inputs, setInputs] = useState({
    artistName: '',
    genre: '',
    category: '',
    bookingPrice: '',
    summary: '',
    bio: '',
    image: null,
  });
  const { artist_id } = useParams();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchHandler = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/artists/${artist_id}`);
        // Assuming your API returns artist data directly or in res.data.user
        const artistData = res.data.user || res.data; 
        setInputs({
          artistName: artistData.artistName || '',
          genre: artistData.genre || '',
          category: artistData.category || '',
          bookingPrice: artistData.bookingPrice || '',
          summary: artistData.summary || '',
          bio: artistData.bio || '',
          image: null, // image file won't be loaded here
        });
      } catch (error) {
        console.error("Failed to fetch artist:", error);
      }
    };

    if (artist_id) {
      fetchHandler();
    }
  }, [artist_id]);

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "image") {
      setInputs((prev) => ({ ...prev, image: files[0] }));
    } else {
      setInputs((prev) => ({ ...prev, [name]: value }));
    }
  };

  const sendRequest = async () => {
    try {
      const formData = new FormData();
      formData.append("artistName", inputs.artistName);
      formData.append("genre", inputs.genre);
      formData.append("category", inputs.category);
      formData.append("bookingPrice", inputs.bookingPrice);
      formData.append("summary", inputs.summary);
      formData.append("bio", inputs.bio);
      if (inputs.image) {
        formData.append("image", inputs.image);
      }

      await axios.put(`http://localhost:5000/artists/${artist_id}`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      navigate("/manage-artists"); // navigate back to manage page after update
    } catch (error) {
      console.error("Failed to update artist:", error);
    }
  };

  return (
    <div>
      <h1>Update Artist Page</h1>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          sendRequest();
        }}
      >
        <input
          type="text"
          name="artistName"
          value={inputs.artistName}
          onChange={handleChange}
          placeholder="Artist Name"
          required
        />
        <br />
        <input
          type="text"
          name="genre"
          value={inputs.genre}
          onChange={handleChange}
          placeholder="Genre"
          required
        />
        <br />
        <input
          type="text"
          name="category"
          value={inputs.category}
          onChange={handleChange}
          placeholder="Category"
          required
        />
        <br />
        <input
          type="number"
          name="bookingPrice"
          value={inputs.bookingPrice}
          onChange={handleChange}
          placeholder="Booking Price"
          required
        />
        <br />
        <textarea
          name="summary"
          value={inputs.summary}
          onChange={handleChange}
          placeholder="Summary"
          required
        />
        <br />
        <textarea
          name="bio"
          value={inputs.bio}
          onChange={handleChange}
          placeholder="Bio"
          required
        />
        <br />
        <input type="file" name="image" onChange={handleChange} />
        <br />
        <button type="submit">Update Artist</button>
      </form>
    </div>
  );
}

export default UpdateArtist;
